svg.script:
(function () {
  var NS = "http://www.w3.org/2000/svg";
  var ruta = document.getElementById("ruta");
  var L = ruta.getTotalLength();
  var HORIZONTE = 207;

  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function pt(f) { return ruta.getPointAtLength(clamp(f, 0, 1) * L); }
  function tan(f) {
    var a = pt(f - 0.004), b = pt(f + 0.004);
    var dx = b.x - a.x, dy = b.y - a.y, m = Math.hypot(dx, dy) || 1;
    return { x: dx / m, y: dy / m };
  }
  // el camino siempre sube en pantalla: y -> f por bisección
  function fDeY(y) {
    var lo = 0, hi = 1;
    for (var i = 0; i < 30; i++) {
      var mid = (lo + hi) / 2;
      if (pt(mid).y > y) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }
  // ancho con perspectiva: proporcional a la distancia bajo el horizonte
  function ancho(y) { return Math.max(3, 0.34 * (y - HORIZONTE) + 4); }

  function poligono(extra) {
    var N = 220, izq = [], der = [];
    for (var i = 0; i <= N; i++) {
      var f = i / N, p = pt(f), t = tan(f), h = ancho(p.y) / 2 + extra(ancho(p.y));
      izq.push((p.x - t.y * h).toFixed(1) + "," + (p.y + t.x * h).toFixed(1));
      der.push((p.x + t.y * h).toFixed(1) + "," + (p.y - t.x * h).toFixed(1));
    }
    return izq.concat(der.reverse()).join(" ");
  }
  document.getElementById("sombra-camino").setAttribute("points", poligono(function (w) { return 4 + w * 0.06; }));
  document.getElementById("orilla").setAttribute("points", poligono(function (w) { return 1 + w * 0.035; }));
  document.getElementById("asfalto").setAttribute("points", poligono(function () { return 0; }));

  // rayas centrales con perspectiva real
  var rayas = document.getElementById("rayas");
  for (var i = 0; i < 160; i++) {
    var ha = 300 / (1 + 0.5 * i), hb = 300 / (1 + 0.5 * (i + 0.45));
    if (ha < 3) break;
    var pa = pt(fDeY(HORIZONTE + ha)), pb = pt(fDeY(HORIZONTE + hb));
    var ln = document.createElementNS(NS, "line");
    ln.setAttribute("x1", pa.x.toFixed(1)); ln.setAttribute("y1", pa.y.toFixed(1));
    ln.setAttribute("x2", pb.x.toFixed(1)); ln.setAttribute("y2", pb.y.toFixed(1));
    ln.setAttribute("stroke-width", (ancho(pa.y) * 0.045 + 0.5).toFixed(2));
    rayas.appendChild(ln);
  }

  // flores y matas extra, evitando la carretera
  var extra = document.getElementById("pasto-extra");
  var sem = 11;
  function rnd() { sem = (sem * 16807) % 2147483647; return sem / 2147483647; }
  function libre(x, y) {
    if (y < 200 || y > 530) return true;
    return Math.abs(x - pt(fDeY(y)).x) > ancho(y) / 2 + 16;
  }
  var puestos = 0, intentos = 0;
  while (puestos < 55 && intentos < 600) {
    intentos++;
    var x = 14 + rnd() * 772, y = 352 + rnd() * 130;
    if (!libre(x, y)) continue;
    var esc = 0.7 + (y - 352) / 130 * 0.7;
    var g = document.createElementNS(NS, "g");
    g.setAttribute("transform", "translate(" + x.toFixed(1) + " " + y.toFixed(1) + ") scale(" + esc.toFixed(2) + ")");
    if (rnd() < 0.55) {
      var alto = 7 + rnd() * 5;
      g.innerHTML = '<path d="M0 0V' + (-alto).toFixed(1) + '" stroke="#5f7a3f" stroke-width="1" fill="none"/>' +
        '<circle cx="0" cy="' + (-alto - 1).toFixed(1) + '" r="1.9" fill="' + (rnd() < 0.5 ? "#f6eab0" : "#fbf8ee") + '"/>';
    } else {
      g.innerHTML = '<path d="M0 0L-4-8M0 0L0-10M0 0L4-8" stroke="#4d6b3e" stroke-width="1.5" fill="none" stroke-linecap="round"/>';
    }
    extra.appendChild(g);
    puestos++;
  }

  // carro y polvo
  var carro = document.getElementById("carro");
  var polvo = document.getElementById("polvo");
  var nubes = [];
  for (var k = 0; k < 9; k++) {
    var c = document.createElementNS(NS, "circle");
    c.setAttribute("fill", "#eee3c9"); c.setAttribute("opacity", "0"); c.setAttribute("r", "1");
    polvo.appendChild(c);
    nubes.push({ el: c, nace: -1, x: 0, y: 0, s: 1 });
  }
  var siguiente = 0, ultimo = 0, inicio = null, DUR = 13000;

  function cuadro(now) {
    if (inicio === null) inicio = now;
    var t = now - inicio, v = ((t % DUR) / DUR) / 0.93;
    if (v > 1) {
      carro.setAttribute("opacity", "0");
    } else {
      var f = fDeY(HORIZONTE + 8 + 322 * Math.pow(1 - v, 1.8));
      var p = pt(f), tg = tan(f), w = ancho(p.y);
      var x = p.x - tg.y * w * 0.24, y = p.y + tg.x * w * 0.24;   // carril derecho
      var s = (0.5 * w) / 66;
      var lean = clamp(Math.atan2(tg.x, -tg.y) * 180 / Math.PI * 0.18, -6, 6);
      var rebote = -Math.abs(Math.sin(t * 0.012)) * 0.9 * s;
      var op = v < 0.03 ? v / 0.03 : (v > 0.94 ? Math.max(0, (1 - v) / 0.06) : 1);
      carro.setAttribute("transform", "translate(" + x.toFixed(1) + " " + (y + rebote).toFixed(1) + ") rotate(" + lean.toFixed(1) + ") scale(" + s.toFixed(3) + ")");
      carro.setAttribute("opacity", op.toFixed(2));
      if (t - ultimo > 170 && v > 0.04 && v < 0.9) {
        ultimo = t;
        var n = nubes[siguiente++ % nubes.length];
        n.nace = t; n.x = x + (Math.random() - 0.5) * 12 * s; n.y = y + 2 * s; n.s = s;
      }
    }
    for (var j = 0; j < nubes.length; j++) {
      var q = nubes[j], e = (t - q.nace) / 1400;
      if (q.nace < 0 || e > 1 || v > 1) { q.el.setAttribute("opacity", "0"); continue; }
      q.el.setAttribute("cx", q.x.toFixed(1));
      q.el.setAttribute("cy", (q.y + e * 5 * q.s).toFixed(1));
      q.el.setAttribute("r", ((3 + e * 9) * q.s).toFixed(2));
      q.el.setAttribute("opacity", ((1 - e) * 0.5).toFixed(2));
    }
    requestAnimationFrame(cuadro);
  }
  requestAnimationFrame(cuadro);
})();
